const items = $input.all();

// This processor is designed to handle exactly
// one prospect per sub-workflow invocation.
if (items.length !== 1) {
  throw new Error(
    `EXPECTED_SINGLE_PROSPECT: received ${items.length}`
  );
}

const prospect = items[0].json;

// Preserve the existing Stage 17 input validation,
// including one-based batch positions.
if (
  !prospect ||
  typeof prospect !== "object" ||
  Array.isArray(prospect) ||
  typeof prospect.batch_id !== "string" ||
  !prospect.batch_id.trim() ||
  typeof prospect.prospect_id !== "string" ||
  !prospect.prospect_id.trim() ||
  !Number.isInteger(prospect.batch_position) ||
  prospect.batch_position < 1 ||
  !Number.isInteger(prospect.batch_size) ||
  prospect.batch_size < 1 ||
  prospect.batch_position > prospect.batch_size ||
  !prospect.crm ||
  typeof prospect.crm !== "object" ||
  Array.isArray(prospect.crm)
) {
  throw new Error("INVALID_PROSPECT_INPUT");
}

// Mock is the default so the public/UAT workflow
// remains replayable without Dust credentials.
const assessmentMode =
  prospect.assessment_mode ?? "mock";

if (
  assessmentMode !== "mock" &&
  assessmentMode !== "live"
) {
  throw new Error("INVALID_ASSESSMENT_MODE");
}

// Optional configuration for live Dust polling.
// The default deadline remains 120 seconds.
const pollingTimeout =
  prospect.polling_timeout_ms ?? 120000;

if (
  typeof pollingTimeout !== "number" ||
  !Number.isInteger(pollingTimeout) ||
  pollingTimeout < 1000 ||
  pollingTimeout > 120000
) {
  throw new Error("INVALID_POLLING_TIMEOUT");
}

// Reinitialise this timestamp for each actual
// processor invocation. Do not trust a caller's
// previous timestamp as the execution deadline.
const processorStartedAt = new Date().toISOString();

return [{
  json: {
    ...prospect,

    assessment_mode: assessmentMode,
    polling_timeout_ms: pollingTimeout,

    processor_status: "INPUT_VALIDATED",
    processor_started_at: processorStartedAt
  },

  // Preserve the input-item pairing used by n8n.
  pairedItem: { item: 0 }
}];

const prospect = $json;

const base = {
  batch_id: prospect.batch_id,
  batch_position: prospect.batch_position,
  batch_size: prospect.batch_size,
  prospect_id: prospect.prospect_id,
  processor_started_at: prospect.processor_started_at
};

// Synthetic Dust response used for UAT.
// P-B004 deliberately produces malformed JSON.
const rawResponse = prospect.prospect_id === "P-B004"
  ? '{"outreach_disposition":'
  : JSON.stringify({
      prospect_id: prospect.prospect_id,
      account_priority: "HIGH",
      prospect_fit: "HIGH",
      outreach_disposition:
        "ADD_TO_PRIORITY_OUTBOUND_QUEUE",
      suppression_applied: false,
      suppression_reason: "NONE",
      decision_summary:
        "Synthetic AI recommendation for governance testing.",
      decision_rationale:
        "Mock decision generated to test real CRM governance."
    });

try {
  const decision = JSON.parse(rawResponse);

  if (
    !decision ||
    typeof decision !== "object" ||
    Array.isArray(decision) ||
    decision.prospect_id !== prospect.prospect_id
  ) {
    throw new Error("INVALID_MOCK_DECISION");
  }

  return {
    json: {
      ...base,
      assessment_status: "READY_FOR_GOVERNANCE",
      source: {
        prospect_id: prospect.prospect_id,
        crm: prospect.crm
      },
      decision,
      error_code: null
    }
  };

} catch (error) {
  const errorCode = error instanceof SyntaxError
    ? "MALFORMED_AI_JSON"
    : "INVALID_MOCK_DECISION";

  return {
    json: {
      ...base,
      assessment_status: "REJECTED",
      source: {
        prospect_id: prospect.prospect_id,
        crm: prospect.crm
      },
      decision: null,
      error_code: errorCode
    }
  };
}

const assessment = $json;

if (assessment.assessment_status !== "REJECTED") {
  throw new Error(
    "EXPECTED_REJECTED_ASSESSMENT"
  );
}

if (
  typeof assessment.prospect_id !== "string" ||
  !assessment.prospect_id.trim() ||
  !assessment.error_code
) {
  throw new Error(
    "INVALID_REJECTION_ENVELOPE"
  );
}

return {
  json: {
    batch_id: assessment.batch_id,
    batch_position: assessment.batch_position,
    batch_size: assessment.batch_size,
    prospect_id: assessment.prospect_id,

    processing_status: "REJECTED",
    action_outcome: null,
    outreach_disposition: null,
    suppression_source: null,
    suppression_reason: null,

    error_code: assessment.error_code,

    decision_summary:
      "Assessment rejected: " +
      assessment.error_code,

    dust_conversation_id:
    assessment.dust_conversation_id ?? null,
    assessment_mode:
    assessment.assessment_mode ?? "mock",
    processed_at: new Date().toISOString()
  }
};

const results = $input.all();

// Exactly one prospect per processor invocation.
if (results.length !== 1) {
  throw new Error("EXPECTED_ONE_GOVERNANCE_RESULT");
}

// Shared validation runs before the mock/live branch.
const original = $(
  "Processor - Validate Prospect Input"
).first().json;

if (
  !original ||
  typeof original.prospect_id !== "string" ||
  !original.prospect_id.trim() ||
  typeof original.batch_id !== "string" ||
  !original.batch_id.trim() ||
  !Number.isInteger(original.batch_position) ||
  !Number.isInteger(original.batch_size)
) {
  throw new Error("INVALID_ORIGINAL_PROSPECT_CONTEXT");
}

const envelope = results[0].json;
const assessmentMode = original.assessment_mode ?? "mock";

if (!["mock", "live"].includes(assessmentMode)) {
  throw new Error("INVALID_ASSESSMENT_MODE");
}

// A live conversation reference must come from the
// successful creation node, not solely from AI output.
let trustedDustConversationId = null;

if (assessmentMode === "live") {
  const creation = $(
    "Processor - Validate Dust Creation"
  ).first().json;

  if (
    creation.dust_create_status !== "CREATED" ||
    typeof creation.dust_conversation_id !== "string" ||
    !creation.dust_conversation_id.trim()
  ) {
    throw new Error("MISSING_TRUSTED_DUST_CONVERSATION");
  }

  trustedDustConversationId =
    creation.dust_conversation_id;
}

const base = {
  batch_id: original.batch_id,
  batch_position: original.batch_position,
  batch_size: original.batch_size,
  prospect_id: original.prospect_id,
  assessment_mode: assessmentMode,

  processing_status: null,
  action_outcome: null,
  outreach_disposition: null,
  suppression_source: null,
  suppression_reason: null,
  error_code: null,
  decision_summary: null,

  dust_conversation_id: trustedDustConversationId,
  processed_at: new Date().toISOString()
};

function reject(code, detail) {
  return {
    ...base,
    processing_status: "REJECTED",
    error_code: code,
    decision_summary: "Governance rejected: " + code,
    error_detail: detail ?? null
  };
}

const allowedDispositions = [
  "ADD_TO_PRIORITY_OUTBOUND_QUEUE",
  "ADD_TO_STANDARD_OUTBOUND_QUEUE",
  "RESEARCH_BETTER_PERSONA",
  "NURTURE_OR_MONITOR",
  "HOLD",
  "DO_NOT_PRIORITISE"
];

const actionOutcomes = {
  ADD_TO_PRIORITY_OUTBOUND_QUEUE: "QUEUED_PRIORITY",
  ADD_TO_STANDARD_OUTBOUND_QUEUE: "QUEUED_STANDARD",
  RESEARCH_BETTER_PERSONA: "PERSONA_RESEARCH",
  NURTURE_OR_MONITOR: "NURTURE",
  HOLD: "HELD",
  DO_NOT_PRIORITISE: "NOT_PRIORITISED"
};

const allowedReasons = [
  "NONE",
  "DO_NOT_CONTACT",
  "OPEN_OPPORTUNITY",
  "EXISTING_CUSTOMER",
  "EXISTING_RELATIONSHIP_OR_OWNER",
  "PREVIOUS_DISQUALIFICATION",
  "RECENT_CONTACT",
  "OTHER"
];

let output;

try {
  // Governance may explicitly reject the assessment.
  if (envelope.execution_status === "REJECTED") {
    output = reject(
      envelope.error_code || "GOVERNANCE_REJECTED",
      "The CRM Governance Engine rejected this record."
    );

  } else {
    if (
      envelope.execution_status !== "PROCESSED" ||
      envelope.error_code !== null
    ) {
      throw new Error("INVALID_GOVERNANCE_ENVELOPE");
    }

    const d = envelope.actual;

    if (
      !d ||
      typeof d !== "object" ||
      Array.isArray(d)
    ) {
      throw new Error("MISSING_GOVERNANCE_DECISION");
    }

    // Protect against cross-prospect result contamination.
    if (d.prospect_id !== original.prospect_id) {
      throw new Error("PROSPECT_ID_MISMATCH");
    }

    // Never accept a conflicting Dust reference.
    if (
      assessmentMode === "live" &&
      d.dust_conversation_id != null &&
      d.dust_conversation_id !== trustedDustConversationId
    ) {
      throw new Error("DUST_CONVERSATION_ID_MISMATCH");
    }

    if (
      !allowedDispositions.includes(
        d.outreach_disposition
      )
    ) {
      throw new Error("INVALID_OUTREACH_DISPOSITION");
    }

    if (
      !["HIGH", "MEDIUM", "LOW"].includes(
        d.account_priority
      ) ||
      !["HIGH", "MEDIUM", "LOW"].includes(
        d.prospect_fit
      )
    ) {
      throw new Error("INVALID_PRIORITY_CLASSIFICATION");
    }

    if (
      !allowedReasons.includes(
        d.suppression_reason
      ) ||
      !allowedReasons.includes(
        d.ai_suppression_reason
      )
    ) {
      throw new Error("INVALID_SUPPRESSION_REASON");
    }

    if (
      !["NONE", "AI", "CRM", "BOTH"].includes(
        d.suppression_source
      )
    ) {
      throw new Error("INVALID_SUPPRESSION_SOURCE");
    }

    if (
      typeof d.suppression_applied !== "boolean" ||
      typeof d.review_required !== "boolean" ||
      !Array.isArray(d.crm_policy_reasons)
    ) {
      throw new Error("INVALID_GOVERNANCE_FIELDS");
    }

    if (
      typeof d.decision_summary !== "string" ||
      !d.decision_summary.trim() ||
      typeof d.decision_rationale !== "string" ||
      !d.decision_rationale.trim()
    ) {
      throw new Error("INVALID_DECISION_EXPLANATION");
    }

    if (
      d.crm_policy_reasons.some(reason =>
        !allowedReasons.includes(reason) ||
        reason === "NONE"
      ) ||
      new Set(d.crm_policy_reasons).size !==
        d.crm_policy_reasons.length
    ) {
      throw new Error("INVALID_CRM_POLICY_REASONS");
    }

    if (
      typeof d.crm_policy_checked_at !== "string" ||
      !Number.isFinite(
        Date.parse(d.crm_policy_checked_at)
      )
    ) {
      throw new Error("INVALID_CRM_POLICY_TIMESTAMP");
    }

    const crmHold =
      d.crm_policy_reasons.length > 0;

    const aiHold =
      d.ai_suppression_reason !== "NONE";

    const mustHold = crmHold || aiHold;

    const expectedSource =
      crmHold && aiHold ? "BOTH" :
      crmHold ? "CRM" :
      aiHold ? "AI" :
      "NONE";

    if (d.suppression_source !== expectedSource) {
      throw new Error("SUPPRESSION_SOURCE_MISMATCH");
    }

    if (
      d.crm_policy_status !==
      (crmHold ? "SUPPRESSED" : "CLEAR")
    ) {
      throw new Error("CRM_POLICY_STATUS_MISMATCH");
    }

    if (
      d.suppression_applied !== mustHold ||
      (d.outreach_disposition === "HOLD") !== mustHold
    ) {
      throw new Error(
        "SUPPRESSION_DISPOSITION_MISMATCH"
      );
    }

    const expectedReason = crmHold
      ? d.crm_policy_reasons[0]
      : aiHold
        ? d.ai_suppression_reason
        : "NONE";

    if (d.suppression_reason !== expectedReason) {
      throw new Error("SUPPRESSION_REASON_MISMATCH");
    }

    if (
      d.review_required !== (aiHold && !crmHold)
    ) {
      throw new Error("REVIEW_FLAG_MISMATCH");
    }

    // All governance checks passed.
    output = {
      ...base,

      processing_status: "COMPLETED",

      action_outcome:
        actionOutcomes[d.outreach_disposition],

      outreach_disposition:
        d.outreach_disposition,

      suppression_source:
        d.suppression_source,

      suppression_reason:
        d.suppression_reason,

      error_code: null,
      decision_summary: d.decision_summary,

      account_priority: d.account_priority,
      prospect_fit: d.prospect_fit,

      review_required: d.review_required,
      crm_policy_status: d.crm_policy_status,
      crm_policy_reasons: d.crm_policy_reasons,

      dust_conversation_id:
        assessmentMode === "live"
          ? trustedDustConversationId
          : d.dust_conversation_id ?? null,

      governance_checked_at:
        d.crm_policy_checked_at,

      final_validation_status: "PASS"
    };
  }

} catch (error) {
  output = reject(
    "INVALID_FINAL_GOVERNANCE_DECISION",
    error.message
  );
}

return [{ json: output }];

const prospect = $json;

if (
  typeof prospect.prospect_id !== "string" ||
  !prospect.prospect_id.trim() ||
  !prospect.crm ||
  typeof prospect.crm !== "object" ||
  Array.isArray(prospect.crm)
) {
  throw new Error("INVALID_LIVE_PROSPECT_INPUT");
}

if (prospect.assessment_mode !== "live") {
  throw new Error("LIVE_MODE_NOT_ENABLED");
}

// Preserve the original record before calling Dust.
// Never derive prospect identity from the AI response.
const source = JSON.parse(JSON.stringify(prospect));

const dustRequestBody = {
  title: null,
  visibility: "unlisted",
  message: {
    content:
      "Assess the following prospect record and return " +
      "the decision using your configured structured " +
      "output contract:\n\n" +
      JSON.stringify(source),

    mentions: [
      {
        configurationId: "YOUR_DUST_AGENT_CONFIGURATION_ID"
      }
    ],

    context: {
      timezone: "Europe/London",
      username: "n8n Finance Signal Integration",
      email: null,
      fullName: "n8n Finance Signal Integration",
      profilePictureUrl: null,
      origin: "api"
    }
  }
};

return {
  json: {
    batch_id: source.batch_id,
    batch_position: source.batch_position,
    batch_size: source.batch_size,
    prospect_id: source.prospect_id,

    assessment_mode: "live",
    processor_started_at:
      source.processor_started_at ??
      new Date().toISOString(),

    source_prospect: source,
    dust_request_body: dustRequestBody
  }
};

const items = $input.all();

if (items.length !== 1) {
  throw new Error("EXPECTED_ONE_DUST_CREATE_RESPONSE");
}

// The processor handles one prospect per invocation.
// Retrieve its context from before the HTTP request.
const original = $(
  "Processor - Prepare Live Dust Request"
).first().json;

const response = items[0].json;

if (
  !original ||
  typeof original.prospect_id !== "string" ||
  typeof original.batch_id !== "string" ||
  !original.source_prospect
) {
  throw new Error("MISSING_ORIGINAL_PROSPECT_CONTEXT");
}

const base = {
  batch_id: original.batch_id,
  batch_position: original.batch_position,
  batch_size: original.batch_size,
  prospect_id: original.prospect_id,
  assessment_mode: "live",
  processor_started_at: original.processor_started_at,
  source_prospect: original.source_prospect
};

const conversationId = response?.conversation?.sId;

const validConversation =
  typeof conversationId === "string" &&
  conversationId.trim().length > 0;

const hasError =
  response?.error != null ||
  response?.statusCode >= 400 ||
  response?.status >= 400;

if (hasError || !validConversation) {
  const rawError =
    response?.error?.message ??
    response?.error ??
    response?.message ??
    "Dust did not return a valid conversation ID";

  return [{
    json: {
      ...base,
      dust_create_status: "FAILED",
      dust_conversation_id: null,
      error_code: "DUST_CREATE_FAILED",
      error_detail: String(rawError),
      checked_at: new Date().toISOString()
    }
  }];
}

return [{
  json: {
    ...base,
    dust_create_status: "CREATED",
    dust_conversation_id: conversationId,
    dust_conversation_created:
      response.conversation.created ?? null,
    error_code: null,
    error_detail: null,
    checked_at: new Date().toISOString()
  }
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error("EXPECTED_ONE_DUST_CREATION_FAILURE");
}

const record = items[0].json;

if (
  record.dust_create_status !== "FAILED" ||
  typeof record.batch_id !== "string" ||
  typeof record.prospect_id !== "string" ||
  !Number.isInteger(record.batch_position) ||
  !Number.isInteger(record.batch_size)
) {
  throw new Error("INVALID_DUST_CREATION_FAILURE_INPUT");
}

return [{
  json: {
    batch_id: record.batch_id,
    batch_position: record.batch_position,
    batch_size: record.batch_size,
    prospect_id: record.prospect_id,

    processing_status: "DUST_API_ERROR",
    action_outcome: null,
    outreach_disposition: null,

    suppression_source: null,
    suppression_reason: null,

    error_code: "DUST_CREATE_FAILED",
    error_detail: record.error_detail ?? null,

    decision_summary:
      "Dust conversation creation failed or returned " +
      "an invalid response. No business action was authorised.",

    dust_conversation_id: null,
    assessment_mode: "live",

    processor_started_at:
      record.processor_started_at ?? null,

    processed_at: new Date().toISOString()
  }
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error(
    "EXPECTED_ONE_DUST_CONVERSATION_RESPONSE"
  );
}

const response = items[0].json;

if (
  !response ||
  typeof response !== "object" ||
  Array.isArray(response)
) {
  throw new Error("INVALID_DUST_HTTP_RESPONSE");
}

const conversation = response.conversation;

// Recognise both HTTP-level failures and
// error objects returned by n8n.
const statusCandidates = [
  response.statusCode,
  response.status,
  response.error?.statusCode,
  response.error?.status
];

const httpError = statusCandidates.some(value => {
  const status = Number(value);
  return Number.isFinite(status) && status >= 400;
});

const hasApiError =
  response.error != null ||
  httpError;

// Dust conversation creation timestamps
// use milliseconds since Unix epoch.
const created = conversation?.created;

const timestampValid =
  typeof created === "number" &&
  Number.isFinite(created) &&
  created >= 1000000000000 &&
  created <= Date.now() + 60000;

const messages = Array.isArray(conversation?.content)
  ? conversation.content.flat()
  : [];

const agentMessages = messages.filter(
  message => message?.type === "agent_message"
);

const latestAgentMessage =
  agentMessages[agentMessages.length - 1] ?? null;

let dust_poll_status;

if (hasApiError || !conversation) {
  dust_poll_status = "API_ERROR";

} else if (!timestampValid) {
  dust_poll_status = "INVALID_TIMESTAMP";

} else if (conversation.hasError === true) {
  dust_poll_status = "AGENT_ERROR";

} else if (conversation.isRunningAgentLoop === true) {
  dust_poll_status = "PROCESSING";

} else if (latestAgentMessage?.status === "failed") {
  dust_poll_status = "AGENT_ERROR";

} else if (
  latestAgentMessage?.status === "succeeded" &&
  typeof latestAgentMessage.content === "string"
) {
  dust_poll_status = "COMPLETED";

} else if (
  latestAgentMessage?.status === "succeeded"
) {
  dust_poll_status = "INVALID_RESPONSE";

} else {
  // No terminal agent response is available yet.
  dust_poll_status = "PROCESSING";
}

return [{
  json: {
    ...response,

    dust_poll_status,

    dust_created_at:
      timestampValid ? created : null,

    dust_elapsed_ms:
      timestampValid ? Date.now() - created : null,

    dust_agent_message_id:
      latestAgentMessage?.sId ?? null,

    dust_agent_status:
      latestAgentMessage?.status ?? null,

    dust_http_error: hasApiError,

    dust_http_status:
      statusCandidates
        .map(value => Number(value))
        .find(value =>
          Number.isFinite(value) &&
          value >= 100
        ) ?? null
  }
}];

