const items = $input.all();

if (items.length !== 1) {
  throw new Error("EXPECTED_ONE_DUST_TIMEOUT");
}

const source = $(
  "Processor - Prepare Live Dust Request"
).first().json;

const poll = items[0].json;

if (
  !source ||
  typeof source.prospect_id !== "string" ||
  !source.prospect_id.trim() ||
  typeof source.batch_id !== "string" ||
  !source.batch_id.trim()
) {
  throw new Error("MISSING_TIMEOUT_PROSPECT_CONTEXT");
}

const startedAt = Date.parse(source.processor_started_at);

const elapsedMs = Number.isFinite(startedAt)
  ? Math.max(0, Date.now() - startedAt)
  : null;

return [{
  json: {
    batch_id: source.batch_id,
    batch_position: source.batch_position,
    batch_size: source.batch_size,
    prospect_id: source.prospect_id,

    assessment_mode: "live",
    processing_status: "TIMED_OUT",
    action_outcome: null,
    outreach_disposition: null,

    suppression_source: null,
    suppression_reason: null,

    error_code: "DUST_POLLING_TIMEOUT",
    error_detail:
      "Dust did not return a completed assessment " +
      "within the configured polling window.",

    decision_summary:
      "The Dust assessment exceeded its polling " +
      "deadline. No business action was authorised.",

    dust_conversation_id:
      source.dust_conversation_id ??
      $(
        "Processor - Validate Dust Creation"
      ).first().json.dust_conversation_id ??
      null,

    dust_last_poll_status: poll.dust_poll_status,
    processor_started_at: source.processor_started_at,
    elapsed_ms: elapsedMs,
    processed_at: new Date().toISOString()
  }
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error("EXPECTED_ONE_DUST_POLL_RESULT");
}

const poll = items[0].json;

const source = $(
  "Processor - Prepare Live Dust Request"
).first().json;

const creation = $(
  "Processor - Validate Dust Creation"
).first().json;

const startedAt = Date.parse(source.processor_started_at);

const configuredTimeout = Number(
  source.source_prospect?.polling_timeout_ms ?? 120000
);

const validTimeout =
  Number.isFinite(configuredTimeout) &&
  configuredTimeout >= 1000 &&
  configuredTimeout <= 120000;

const elapsedMs = Number.isFinite(startedAt)
  ? Math.max(0, Date.now() - startedAt)
  : null;

const base = {
  batch_id: source.batch_id,
  batch_position: source.batch_position,
  batch_size: source.batch_size,
  prospect_id: source.prospect_id,
  assessment_mode: "live",
  processor_started_at: source.processor_started_at,
  source_prospect: source.source_prospect,
  dust_conversation_id: creation.dust_conversation_id,
  elapsed_ms: elapsedMs,
  dust_poll_status: poll.dust_poll_status,
  dust_response: poll
};

let resolution = "FAILED";
let errorCode = null;

if (!validTimeout || elapsedMs === null) {
  errorCode = "INVALID_POLLING_CONFIGURATION";

} else if (
  poll.conversation?.sId &&
  poll.conversation.sId !== creation.dust_conversation_id
) {
  errorCode = "DUST_CONVERSATION_ID_MISMATCH";

} else if (elapsedMs >= configuredTimeout) {
  errorCode = "DUST_POLLING_TIMEOUT";

} else if (
  poll.error != null ||
  Number(poll.statusCode ?? poll.status ?? 0) >= 400 ||
  poll.dust_poll_status === "API_ERROR"
) {
  errorCode = "DUST_GET_FAILED";

} else if (poll.dust_poll_status === "INVALID_TIMESTAMP") {
  errorCode = "INVALID_DUST_TIMESTAMP";

} else if (poll.dust_poll_status === "AGENT_ERROR") {
  errorCode = "DUST_AGENT_FAILED";

} else if (
  poll.dust_poll_status === "COMPLETED" &&
  poll.conversation?.sId === creation.dust_conversation_id
) {
  resolution = "COMPLETED";

} else {
  errorCode = "INVALID_DUST_RESPONSE";
}

return [{
  json: {
    ...base,
    dust_resolution: resolution,
    error_code: errorCode,
    resolved_at: new Date().toISOString()
  }
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error("EXPECTED_ONE_FAILED_DUST_ASSESSMENT");
}

const record = items[0].json;

if (
  record.dust_resolution !== "FAILED" ||
  typeof record.prospect_id !== "string" ||
  !record.prospect_id.trim() ||
  typeof record.error_code !== "string" ||
  !record.error_code.trim()
) {
  throw new Error("INVALID_DUST_FAILURE_RECORD");
}

const code = record.error_code;

let processingStatus;

if (code === "DUST_POLLING_TIMEOUT") {
  processingStatus = "TIMED_OUT";

} else if (code === "DUST_GET_FAILED") {
  processingStatus = "DUST_API_ERROR";

} else {
  processingStatus = "INVALID_DUST_RESPONSE";
}

return [{
  json: {
    batch_id: record.batch_id,
    batch_position: record.batch_position,
    batch_size: record.batch_size,
    prospect_id: record.prospect_id,

    assessment_mode: "live",
    processing_status: processingStatus,
    action_outcome: null,
    outreach_disposition: null,

    suppression_source: null,
    suppression_reason: null,

    error_code: code,
    error_detail:
      "Dust assessment did not complete successfully: " + code,

    decision_summary:
      "The Dust assessment could not be completed. " +
      "No business action was authorised.",

    dust_conversation_id:
      record.dust_conversation_id ?? null,
    processor_started_at: record.processor_started_at,
    elapsed_ms: record.elapsed_ms,
    processed_at: new Date().toISOString()
  }
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error("EXPECTED_ONE_COMPLETED_DUST_RESULT");
}

const record = items[0].json;

const base = {
  batch_id: record.batch_id,
  batch_position: record.batch_position,
  batch_size: record.batch_size,
  prospect_id: record.prospect_id,
  assessment_mode: "live",
  source_prospect: record.source_prospect,
  processor_started_at: record.processor_started_at,
  dust_conversation_id: record.dust_conversation_id
};

function reject(code, detail) {
  return [{
    json: {
      ...base,
      live_parse_status: "REJECTED",
      decision: null,
      error_code: code,
      error_detail: detail,
      processed_at: new Date().toISOString()
    }
  }];
}

if (record.dust_resolution !== "COMPLETED") {
  return reject(
    "DUST_NOT_COMPLETED",
    "Dust assessment has not completed successfully."
  );
}

const conversation = record.dust_response?.conversation;

if (
  !conversation ||
  conversation.sId !== record.dust_conversation_id ||
  conversation.hasError === true ||
  conversation.isRunningAgentLoop === true ||
  !Array.isArray(conversation.content)
) {
  return reject(
    "INVALID_DUST_RESPONSE",
    "Completed Dust conversation failed integrity checks."
  );
}

const messages = conversation.content.flat();

const agentMessages = messages.filter(
  message => message?.type === "agent_message"
);

const latest = agentMessages[agentMessages.length - 1];

if (
  !latest ||
  latest.status !== "succeeded" ||
  typeof latest.content !== "string"
) {
  return reject(
    "INVALID_DUST_AGENT_MESSAGE",
    "No successful structured agent message was found."
  );
}

let decision;

try {
  decision = JSON.parse(latest.content);
} catch (error) {
  return reject(
    "MALFORMED_AI_JSON",
    "Dust returned an invalid JSON decision: " +
      error.message
  );
}

if (
  !decision ||
  typeof decision !== "object" ||
  Array.isArray(decision)
) {
  return reject(
    "INVALID_AI_DECISION",
    "Dust decision must be a JSON object."
  );
}

if (decision.prospect_id !== record.prospect_id) {
  return reject(
    "PROSPECT_ID_MISMATCH",
    "Dust decision prospect ID differs from the original input."
  );
}

return [{
  json: {
    ...base,
    live_parse_status: "PARSED",
    decision: {
      ...decision,
      dust_conversation_id: record.dust_conversation_id,
      dust_agent_message_id: latest.sId ?? null,
      dust_cost_credits: latest.costCredits ?? null,
      dust_status: latest.status
    },
    error_code: null,
    error_detail: null,
    parsed_at: new Date().toISOString()
  }
}];

const items = $input.all();

if (items.length !== 1) {
  throw new Error("EXPECTED_ONE_LIVE_PARSE_RESULT");
}

const record = items[0].json;

const sourceProspect = record.source_prospect;

if (
  !sourceProspect ||
  typeof sourceProspect !== "object" ||
  Array.isArray(sourceProspect) ||
  typeof record.prospect_id !== "string" ||
  !record.prospect_id.trim() ||
  sourceProspect.prospect_id !== record.prospect_id ||
  !sourceProspect.crm ||
  typeof sourceProspect.crm !== "object" ||
  Array.isArray(sourceProspect.crm)
) {
  throw new Error("INVALID_LIVE_SOURCE_CONTEXT");
}

const base = {
  batch_id: record.batch_id,
  batch_position: record.batch_position,
  batch_size: record.batch_size,
  prospect_id: record.prospect_id,
  processor_started_at: record.processor_started_at,

  assessment_mode: "live",

  source: {
    prospect_id: sourceProspect.prospect_id,
    crm: sourceProspect.crm
  },

  dust_conversation_id:
    record.dust_conversation_id ?? null
};

function rejected(code) {
  return [{
    json: {
      ...base,
      assessment_status: "REJECTED",
      decision: null,
      error_code: code
    }
  }];
}

// The parser has already classified malformed
// JSON and invalid Dust conversation responses.
if (record.live_parse_status === "REJECTED") {
  return rejected(
    record.error_code || "INVALID_DUST_RESPONSE"
  );
}

if (
  record.live_parse_status !== "PARSED" ||
  record.error_code !== null
) {
  return rejected("INVALID_LIVE_PARSE_STATUS");
}

const d = record.decision;

if (
  !d ||
  typeof d !== "object" ||
  Array.isArray(d) ||
  d.prospect_id !== record.prospect_id
) {
  return rejected("INVALID_AI_DECISION");
}

const priorities = ["HIGH", "MEDIUM", "LOW"];

const dispositions = [
  "ADD_TO_PRIORITY_OUTBOUND_QUEUE",
  "ADD_TO_STANDARD_OUTBOUND_QUEUE",
  "RESEARCH_BETTER_PERSONA",
  "NURTURE_OR_MONITOR",
  "HOLD",
  "DO_NOT_PRIORITISE"
];

const reasons = [
  "NONE",
  "DO_NOT_CONTACT",
  "OPEN_OPPORTUNITY",
  "EXISTING_CUSTOMER",
  "EXISTING_RELATIONSHIP_OR_OWNER",
  "PREVIOUS_DISQUALIFICATION",
  "RECENT_CONTACT",
  "OTHER"
];

if (
  !priorities.includes(d.account_priority) ||
  !priorities.includes(d.prospect_fit) ||
  !dispositions.includes(d.outreach_disposition) ||
  typeof d.suppression_applied !== "boolean" ||
  !reasons.includes(d.suppression_reason) ||
  typeof d.decision_summary !== "string" ||
  !d.decision_summary.trim() ||
  typeof d.decision_rationale !== "string" ||
  !d.decision_rationale.trim()
) {
  return rejected("INVALID_AI_DECISION_CONTRACT");
}

return [{
  json: {
    ...base,
    assessment_status: "READY_FOR_GOVERNANCE",
    decision: d,
    error_code: null
  }
}];
